func TestFilesService_Add(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("Content-Type"); !strings.HasPrefix(got, "multipart/form-data; boundary=") {
			t.Fatalf("unexpected content type: %q", got)
		}
		part, header, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("multipart file part: %v", err)
		}
		defer part.Close()
		if header.Filename != "upload.txt" {
			t.Fatalf("unexpected filename: %q", header.Filename)
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read multipart file: %v", err)
		}
		if string(data) != "file" {
			t.Fatalf("unexpected file content: %q", string(data))
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "upload.txt", strings.NewReader("file"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 12 || file.Name != "upload.txt" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func TestFilesService_Add_RequiresFileNameAndContent(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		t.Fatalf("unexpected request: %s %s", r.Method, r.URL.Path)
	})

	if _, err := client.Files.Add(context.Background(), "", strings.NewReader("file")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, err := client.Files.Add(context.Background(), "upload.txt", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

func TestFilesService_Add_RetriesOn429(t *testing.T) {
	t.Parallel()

	policy := pipedrive.DefaultRetryPolicy()
	policy.RetryAllMethods = true
	policy.BaseDelay = time.Millisecond
	policy.MaxDelay = time.Millisecond
	policy.Jitter = func(d time.Duration) time.Duration { return d }

	var bodies []string
	client := newTestClientWithConfig(t, pipedrive.Config{RetryPolicy: &policy}, func(w http.ResponseWriter, r *http.Request) {
		part, _, err := r.FormFile("file")
		if err != nil {
			t.Fatalf("multipart file part: %v", err)
		}
		data, err := io.ReadAll(part)
		_ = part.Close()
		if err != nil {
			t.Fatalf("read multipart file: %v", err)
		}
		bodies = append(bodies, string(data))

		if len(bodies) == 1 {
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"success":false,"error":"rate limited"}`))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	// Simulate os.Open: a reader http.NewRequest cannot replay on its own,
	// so retries are only possible if the service buffers the upload.
	content := struct{ io.Reader }{strings.NewReader("file")}
	file, err := client.Files.Add(context.Background(), "upload.txt", content)
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
	if len(bodies) != 2 {
		t.Fatalf("expected 2 attempts, got %d", len(bodies))
	}
	for i, body := range bodies {
		if body != "file" {
			t.Fatalf("attempt %d sent body %q, want full upload", i+1, body)
		}
	}
}

